"""Shared GitHub Actions workflow template for architecture drift checks.

The same workflow is written by 'cerebrofy arch init --ci' and automatically
by 'cerebrofy init --ai' so that every AI-assisted project ships with the
architecture gate in CI (spec: "Auto-generated by cerebrofy init --ai").
"""

from __future__ import annotations

from pathlib import Path

CI_WORKFLOW_PATH = Path(".github") / "workflows" / "cerebrofy-arch.yml"

CI_WORKFLOW = """\
# Auto-generated by 'cerebrofy arch init --ci' or 'cerebrofy init --ai'.
name: Cerebrofy Architecture Check

on:
  pull_request:
  push:
    branches: [master, main]

jobs:
  arch-check:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 0
      - uses: actions/setup-python@v5
        with:
          python-version: "3.11"
      - name: Install Cerebrofy
        run: python -m pip install --upgrade cerebrofy
      - name: Build the index
        run: cerebrofy build
      - name: Architecture rules check
        run: cerebrofy arch check --format github-annotations
"""


def write_ci_workflow(root: Path, force: bool = False) -> bool:
    """Write the arch CI workflow under *root*.

    Returns True when the workflow file was written, False when it already
    exists and *force* is False.
    """
    path = root / CI_WORKFLOW_PATH
    if path.exists() and not force:
        return False
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(CI_WORKFLOW, encoding="utf-8")
    return True
